files.content:
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  background: #1a1c2c;
  font-family: "Courier New", monospace;
  display: flex;
  min-height: 100vh;
  align-items: center;
  justify-content: center;
}
.calculator {
  background: #f4f4f4;
  border: 4px solid #000;
  box-shadow: 8px 8px 0 #000;
  padding: 1.5rem;
  width: min(320px, 90vw);
}
.calculator h1 {
  font-size: 1.5rem;
  text-align: center;
  margin-bottom: 1rem;
  text-transform: uppercase;
  letter-spacing: 2px;
}
.field {
  display: flex;
  flex-direction: column;
  margin-bottom: 0.75rem;
}
label {
  font-weight: bold;
  margin-bottom: 0.25rem;
}
input, select, button, output {
  font-family: inherit;
  font-size: 1rem;
  padding: 0.5rem;
  border: 3px solid #000;
  background: #fff;
  width: 100%;
}
input:focus, select:focus, button:focus, output:focus {
  outline: 3px solid #f4a261;
  outline-offset: 2px;
}
button {
  background: #e76f51;
  color: #fff;
  cursor: pointer;
  font-weight: bold;
  text-transform: uppercase;
}
button:hover { background: #d65a3b; }
#result {
  display: block;
  text-align: right;
  background: #1a1c2c;
  color: #7fdbca;
  font-size: 1.5rem;
  margin-top: 0.5rem;
}

const $ = (id) => document.getElementById(id);

function calculate() {
  const left = $('left').value.trim();
  const right = $('right').value.trim();
  const out = $('result');

  if (left === '' || right === '') {
    out.textContent = 'Error';
    return;
  }

  const a = Number(left);
  const b = Number(right);

  if (!Number.isFinite(a) || !Number.isFinite(b)) {
    out.textContent = 'Error';
    return;
  }

  const op = $('operation').value;

  if (op === 'divide' && b === 0) {
    out.textContent = 'Error';
    return;
  }

  let answer;
  switch (op) {
    case 'add': answer = a + b; break;
    case 'subtract': answer = a - b; break;
    case 'multiply': answer = a * b; break;
    case 'divide': answer = a / b; break;
    default: out.textContent = 'Error'; return;
  }
  out.textContent = String(answer);
}

$('calculate').addEventListener('click', calculate);

document.addEventListener('keydown', (event) => {
  if (event.key === 'Enter' && event.target.tagName !== 'BUTTON') {
    calculate();
  }
});
